<template>
  <div class="evaluation-page">
    <div class="page-heading"><div><h2>评测测试</h2><p>批量验证法律问答、合同审查和文书摘要的效果与资源消耗。</p></div><el-tag type="info">SQLite · LLM-as-judge</el-tag></div>
    <el-card shadow="never" class="create-card"><template #header>测试集管理</template><el-form inline><el-form-item label="任务名称"><el-input v-model="name" placeholder="例如：法律问答回归集" /></el-form-item><el-form-item label="业务类型"><el-select v-model="category"><el-option label="法律问答" value="legal_qa"/><el-option label="合同审查" value="contract_review"/><el-option label="文书摘要" value="document_summary"/></el-select></el-form-item><el-form-item><input ref="datasetInput" class="file-input" type="file" accept=".json,.csv" @change="pickDataset"/><el-button @click="datasetInput?.click()">选择 JSON/CSV</el-button><span v-if="dataset">{{ dataset.name }}</span></el-form-item><el-form-item><el-button type="primary" :disabled="!name" @click="create">新建测试任务</el-button></el-form-item></el-form><el-divider/><el-form inline><el-form-item label="问题"><el-input v-model="question" placeholder="输入测试问题" style="width:300px" /></el-form-item><el-form-item label="标准答案"><el-input v-model="reference" placeholder="输入标准答案" style="width:300px" /></el-form-item><el-form-item><input ref="attachmentInput" class="file-input" type="file" accept=".pdf,.docx,.txt,.md,.xlsx,.xlsm" @change="pickAttachment"/><el-button @click="attachmentInput?.click()">可选附件</el-button><span v-if="attachment">{{ attachment.name }}</span></el-form-item><el-button :disabled="!selectedTask || !question || !reference" @click="add">添加单条样本</el-button></el-form></el-card>
    <el-card shadow="never"><template #header><div class="report-header"><span>测试报告</span><el-select v-model="selectedTask" placeholder="选择历史任务" @change="loadReport" style="width:300px"><el-option v-for="item in tasks" :key="item.id" :label="`${item.name} · ${item.status}`" :value="item.id"/></el-select><span><el-button v-if="selectedTask && report?.task?.status !== 'running'" type="primary" @click="start">启动测试</el-button><el-button v-if="selectedTask && report?.task?.status === 'running'" type="warning" @click="stop">停止</el-button><el-button v-if="selectedTask" @click="download">导出 CSV</el-button></span></div></template><el-empty v-if="!report" description="先创建或选择测试任务"/><template v-else><el-progress v-if="report.task.status === 'running'" :percentage="progress" /><div class="metrics"><el-statistic title="样本总数" :value="report.summary.total"/><el-statistic title="平均 Judge 分" :value="report.summary.avg_judge_score"/><el-statistic title="通过 / 不合格" :value="`${report.summary.passed} / ${report.summary.failed}`"/><el-statistic title="平均总 Token" :value="report.summary.avg_total_tokens"/><el-statistic title="平均召回耗时(ms)" :value="report.summary.avg_retrieval_ms"/><el-statistic title="平均推理耗时(ms)" :value="report.summary.avg_llm_ms"/><el-statistic title="缓存命中率" :value="`${Math.round(report.summary.cache_hit_rate*100)}%`"/></div><el-table :data="report.samples" border stripe><el-table-column prop="question" label="问题" min-width="220" show-overflow-tooltip/><el-table-column prop="reference_answer" label="标准答案" min-width="220" show-overflow-tooltip/><el-table-column prop="predicted_answer" label="模型输出" min-width="260" show-overflow-tooltip/><el-table-column prop="judge_score" label="Judge" width="80"/><el-table-column prop="total_tokens" label="Token" width="90"/><el-table-column prop="usage_source" label="Token来源" width="100"/><el-table-column prop="total_ms" label="耗时(ms)" width="100"/><el-table-column type="expand"><template #default="scope"><pre>{{ JSON.stringify(scope.row, null, 2) }}</pre></template></el-table-column></el-table></template></el-card>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { evaluationApi } from '@/api/evaluation'
const tasks=ref<any[]>([]), selectedTask=ref(''), report=ref<any>(null), name=ref(''), category=ref('legal_qa'), dataset=ref<File|null>(null), question=ref(''), reference=ref(''), attachment=ref<File|null>(null), datasetInput=ref<HTMLInputElement|null>(null), attachmentInput=ref<HTMLInputElement|null>(null)
const progress=computed(()=>report.value?.task?.total_samples ? Math.round((report.value.task.completed_samples/report.value.task.total_samples)*100) : 0)
function pickDataset(e:Event){dataset.value=(e.target as HTMLInputElement).files?.[0] || null;(e.target as HTMLInputElement).value=''}; function pickAttachment(e:Event){attachment.value=(e.target as HTMLInputElement).files?.[0] || null;(e.target as HTMLInputElement).value=''}
async function refresh(){tasks.value=(await evaluationApi.tasks()).data.items;if(!selectedTask.value && tasks.value[0]){selectedTask.value=tasks.value[0].id;await loadReport()}}
async function create(){const form=new FormData();form.append('name',name.value);form.append('category',category.value);if(dataset.value)form.append('dataset',dataset.value);const result=await evaluationApi.create(form);selectedTask.value=result.data.task_id;name.value='';dataset.value=null;await refresh();await loadReport();ElMessage.success('测试任务已创建')}
async function add(){if(!selectedTask.value)return;const form=new FormData();form.append('question',question.value);form.append('reference_answer',reference.value);form.append('category',category.value);if(attachment.value)form.append('attachment',attachment.value);await evaluationApi.addSampleWithAttachment(selectedTask.value,form);question.value='';reference.value='';attachment.value=null;await loadReport()}
async function loadReport(){if(selectedTask.value)report.value=(await evaluationApi.report(selectedTask.value)).data}
async function start(){await evaluationApi.start(selectedTask.value);await loadReport();const timer=window.setInterval(async()=>{await loadReport();if(report.value?.task?.status!=='running')window.clearInterval(timer)},1500)}
async function stop(){await evaluationApi.stop(selectedTask.value);await loadReport()}; async function download(){const response=await evaluationApi.export(selectedTask.value);const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download=`evaluation-${selectedTask.value}.csv`;a.click();URL.revokeObjectURL(url)}; onMounted(refresh)
</script>
<style scoped>.evaluation-page{max-width:1280px}.page-heading,.report-header{display:flex;align-items:center;justify-content:space-between;gap:16px}.page-heading h2{margin:0 0 6px}.page-heading p{color:#8c8c8c}.create-card{margin-bottom:16px}.file-input{display:none}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:16px;margin:20px 0}pre{white-space:pre-wrap;background:#f6f7f9;padding:12px;border-radius:5px;max-height:360px;overflow:auto}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.report-header{flex-wrap:wrap}}</style>



